for (const lang of LANGS) {
  const patch = MINI[lang];
  if (!patch) continue;
  const out = JSON.parse(JSON.stringify(en));
  out.gradendex.ui = { ...out.gradendex.ui, ...patch.ui };
  out.gradendex.page = { ...out.gradendex.page, ...patch.page };
  fs.writeFileSync(
    path.join(i18nDir, `gradendex.${lang}.json`),
    JSON.stringify(out, null, 2) + '\n'
  );
  console.log('Wrote gradendex.' + lang + '.json');
}
